package com.coworkhub.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.util.*;
@Entity @Table(name="rooms",uniqueConstraints=@UniqueConstraint(columnNames={"location_id","name"})) public class Room { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) @jakarta.validation.constraints.NotBlank public String name; @Enumerated(EnumType.STRING) @jakarta.validation.constraints.NotNull public Enums.RoomType type; @jakarta.validation.constraints.Positive public int capacity; @Column(precision=10,scale=2) @jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero public BigDecimal hourlyRate; public boolean active=true; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="location_id",nullable=false) public Location location; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="room_equipment",joinColumns=@JoinColumn(name="room_id"),inverseJoinColumns=@JoinColumn(name="equipment_id")) public Set<Equipment> equipment=new HashSet<>(); public Room(){} }
